#include<iostream>
#include<cstdio>
#include<cstring>
#include<algorithm>
using namespace std;

int n, k, p;

int power(int base, int exp) {
    int res = 1;
    int cur = base;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * cur % p;
        cur = (long long)cur * cur % p;
        exp >>= 1;
    }
    return res;
}

int lowbit(int x) {
    return x & (-x);
}

int memo[30][250005];
int fact[250005], inv_fact[250005];

void prepare() {
    fact[0] = 1;
    for (int i = 1; i <= n; i++)
        fact[i] = (long long)fact[i - 1] * i % p;
    inv_fact[n] = power(fact[n], p - 2);
    for (int i = n; i >= 1; i--)
        inv_fact[i - 1] = (long long)inv_fact[i] * i % p;
}

int solve(int index, int mask) {
    if (memo[index][mask] != -1)
        return memo[index][mask];
    if (mask == 0) {
        int res = fact[n];
        for (int i = 1; i <= index; i++)
            res = (long long)res * (k - i + 1) % p;
        return memo[index][mask] = res;
    }
    int total = 0;
    int remaining = mask - lowbit(mask);
    for (int subset = remaining; subset; subset = (subset - 1) & remaining)
        total = (total + (long long)inv_fact[mask - subset] * solve(index + 1, subset)) % p;
    total = (total + (long long)inv_fact[mask] * solve(index + 1, 0)) % p;
    return memo[index][mask] = total;
}

int main() {
    scanf("%d %d %d", &n, &k, &p);
    int result = 1;
    for (int i = 1; i <= n; i++)
        result = (long long)result * k % p;
    if (n % 2 == 0) {
        memset(memo, -1, sizeof(memo));
        prepare();
        result = (result - solve(0, n) + p) % p;
    }
    printf("%d\n", result);
    return 0;
}
